sys_script_client.script:
function onSubmit() {

    /*Artifacts involved: 
	MSSCUSTODY-5197
	1) Client Script - MSS Task Prepopulate Amend from Trade - To pass Trade ID and Set values for Field
	2) Script Include - MSSCustodyAmendUtils Method - getTradeFieldvalues - To retrive Values from trade and send back to client
	3) Client Script - MSS Task Create Bulk for Amend - To pass values from bulk extended fields and send to below script inlcude to create bulk record
	4) Script Include - MSSAmendUtilsCore - Create bulk record and map to the task
	This method is to prepropulate the amend fields for automated task when the outcome is selected as Amend related outcomes
    Once the form is submitted, this method executes and populates thefield values from the trade
	*/

    /*
    Eligibility Check Artifacts: 
    Script Include : x_hsb11_mss_c_proc.MSSCustodyAmendUtils - evalAmendEligibility
    System Property: x_hsb11_mss_c_proc.enableautomatedamend.market - Only available markets will allow this script to execute
    System Property: x_hsb11_mss_c_proc.enableautomatedamend.outcomes - Only available markets will allow this script to execute
    */

    if ((g_form.getValue('state') == 2) && (g_form.getValue('trade_task_type') == 'Maker') && (g_form.getValue('bulk_id') == '')) { //from work in progress to closed complete
        var eligbleCheck = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyAmendUtils');
        eligbleCheck.addParam('sysparm_name', 'evalAmendEligibility');
        eligbleCheck.addParam('sysparm_recOutcome', g_form.getValue('outcome'));
        eligbleCheck.addParam('sysparm_recSysID', g_form.getUniqueValue());
        eligbleCheck.addParam('sysparm_tableName', 'x_hsb11_mss_c_proc_mss_custody_task');
        eligbleCheck.getXMLAnswer(handleEligiblity);
    }

    function handleEligiblity(check) {
        if (check.toString() == 'true') {


            //handling the remote table fields
            var tasksecurityID = g_form.getDisplayBox('bulk_id.amend_security_id_sec_id_ref').value ? g_form.getDisplayBox('bulk_id.amend_security_id_sec_id_ref').value : g_form.getValue('bulk_id.security_id_sec_id');
            var taskcounterParCode = g_form.getDisplayBox('bulk_id.amend_counterparty_code_ref').value ? g_form.getDisplayBox('bulk_id.amend_counterparty_code_ref').value : g_form.getValue('bulk_id.amend_counterparty_code');
            var taskswitchAcc = g_form.getDisplayBox('bulk_id.amend_switch_account_ref').value ? g_form.getDisplayBox('bulk_id.amend_switch_account_ref').value : g_form.getValue('bulk_id.amend_switch_account');
            //handling the remote table fields
            var tasktradeDate = g_form.getValue("bulk_id.amend_trade_date");
            var tasksettlementDate = g_form.getValue("bulk_id.settlement_date");
            var taskdealPrice = g_form.getValue("bulk_id.amend_deal_price");
            var taskdealCurrency = g_form.getValue("bulk_id.amend_deal_currency");
            var tasksettlementCurrency = g_form.getValue("bulk_id.amend_settlement_currency");
            var tasksettlementAmount = g_form.getValue("bulk_id.amend_settlement_amount");
            var taskcounterPartyRef = g_form.getValue("bulk_id.counterparty_reference");
            var taskcusRef = g_form.getValue("bulk_id.customer_reference");
            var tasklocCode = g_form.getValue("bulk_id.amend_location_code");
            var taskhmiIndicator = g_form.getValue("bulk_id.amend_hmi_indicator");
            var taskscripholIndicator = g_form.getValue("bulk_id.amend_script_hold_indicator");
            var taskcashHoldIndicator = g_form.getValue("bulk_id.amend_cash_hold_indicator");
            var taskgdiIncidcator = g_form.getValue("bulk_id.amend_gdi_indicator");
            var taskpayMethod = g_form.getValue("bulk_id.amend_payment_method");
            var taskswitchIndicator = g_form.getValue("bulk_id.amend_switch_indicator");
            var tasksusAccNum = g_form.getValue("bulk_id.amend_suspense_account_number");
            var taskcounterSettAccNum = g_form.getValue("bulk_id.amend_counterparty_settlement_account_number");
            var taskconverAccSwitch = g_form.getValue("bulk_id.amend_convert_to_account_switching");
            var taskaccOfClient = g_form.getValue("bulk_id.amend_a_c_of_client");
            var taskdelivererCusBic = g_form.getValue("bulk_id.amend_deliverer_custodian_bic_receiver_custodian_bic");
            var tasksellBuyBic = g_form.getValue("bulk_id.amend_seller_bic_buyer_bic");
            var taskplaceofSett = g_form.getValue("bulk_id.amend_place_of_settlement_bic");
            var taskamendChargesType = g_form.getValue("bulk_id.amend_charges_type");
            var taskamendChargesCCY = g_form.getValue("bulk_id.amend_charges_ccy");
            var taskamendChargesAMT = g_form.getValue("bulk_id.amend_charges_amt");
            var taskamendNSSC = g_form.getValue("bulk_id.amend_nssc");


            var checkIfAmended = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyAmendUtils');
            checkIfAmended.addParam('sysparm_name', 'amendEvaluateIfAmended');
            checkIfAmended.addParam('sysparm_tradeID', g_form.getValue('trade_id'));
            checkIfAmended.addParam('sysparm_tasksecurityID', tasksecurityID);
            checkIfAmended.addParam('sysparm_taskcounterParCode', taskcounterParCode);
            checkIfAmended.addParam('sysparm_taskswitchAcc', taskswitchAcc);
            checkIfAmended.addParam('sysparm_tasktradeDate ', tasktradeDate);
            checkIfAmended.addParam('sysparm_tasksettlementDate', tasksettlementDate);
            checkIfAmended.addParam('sysparm_taskdealPrice ', taskdealPrice);
            checkIfAmended.addParam('sysparm_taskdealCurrency', taskdealCurrency);
            checkIfAmended.addParam('sysparm_tasksettlementCurrency', tasksettlementCurrency);
            checkIfAmended.addParam('sysparm_tasksettlementAmount', tasksettlementAmount);
            checkIfAmended.addParam('sysparm_taskcounterPartyRef', taskcounterPartyRef);
            checkIfAmended.addParam('sysparm_taskcusRef', taskcusRef);
            checkIfAmended.addParam('sysparm_tasklocCode', tasklocCode);
            checkIfAmended.addParam('sysparm_taskhmiIndicator', taskhmiIndicator);
            checkIfAmended.addParam('sysparm_taskscripholIndicator', taskscripholIndicator);
            checkIfAmended.addParam('sysparm_taskcashHoldIndicator', taskcashHoldIndicator);
            checkIfAmended.addParam('sysparm_taskgdiIncidcator', taskgdiIncidcator);
            checkIfAmended.addParam('sysparm_taskpayMethod', taskpayMethod);
            checkIfAmended.addParam('sysparm_taskswitchIndicator', taskswitchIndicator);
            checkIfAmended.addParam('sysparm_tasksusAccNum', tasksusAccNum);
            checkIfAmended.addParam('sysparm_taskcounterSettAccNum', taskcounterSettAccNum);
            checkIfAmended.addParam('sysparm_taskconverAccSwitch', taskconverAccSwitch);
            checkIfAmended.addParam('sysparm_taskaccOfClient', taskaccOfClient);
            checkIfAmended.addParam('sysparm_taskdelivererCusBic', taskdelivererCusBic);
            checkIfAmended.addParam('sysparm_tasksellBuyBic', tasksellBuyBic);
            checkIfAmended.addParam('sysparm_taskplaceofSett', taskplaceofSett);
            checkIfAmended.addParam('sysparm_taskamendChargesType', taskamendChargesType);
            checkIfAmended.addParam('sysparm_taskamendChargesCCY', taskamendChargesCCY);
            checkIfAmended.addParam('sysparm_taskamendChargesAMT', taskamendChargesAMT);
            checkIfAmended.addParam('sysparm_taskamendNSSC', taskamendNSSC);
            checkIfAmended.getXMLAnswer(handleResponse);

        }

        function handleResponse(answer) {

            g_form.addErrorMessage('Amend Allow ' + answer);
            return answer;
        }

    }


}
